// Generated by hecks site site_projection.project_site. Do not edit.

// A record's History: what was changed through this editor, newest first, by whom and when, with
// what each change altered, and for a change that edited the record a button that puts it back as
// it was before that change. The list is the editor's own (see ../history.ts); it says so.
import { sameValue } from "../commands.ts";
import { EDITOR } from "../config.ts";
import type { Entry } from "../history.ts";
import { at, qualified } from "../names.ts";
import { SCHEMA } from "../schema.ts";
import type { Aggregate, Attr, Command } from "../schema.ts";
import { esc, href } from "./html.ts";
import { momentTime } from "./moments.ts";
import { labelOf } from "./words.ts";

type State = Record<string, unknown>;

/** The most entries a panel lists; the rest are counted. */
const SHOWN = 15;

const aggregateOf = (name: string): Aggregate | undefined => SCHEMA.aggregates.find((agg) => qualified(agg) === name);

/** The text a value says, for a line of "was ... now ...": one plain part, a count for a list, a clip of long text. */
function brief(value: unknown): string {
  if (value === null || value === undefined || value === "") return "nothing";
  if (Array.isArray(value)) return value.length === 0 ? "nothing" : `${value.length} ${value.length === 1 ? "item" : "items"}`;
  if (typeof value === "object") {
    const parts = Object.values(value as object).filter((part) => part !== null && part !== undefined);
    if (parts.length === 1 && typeof parts[0] !== "object") return brief(parts[0]);
    return "changed";
  }
  const text = String(value).replace(/\s+/g, " ").trim();
  return text.length > 60 ? `${text.slice(0, 57)}...` : text;
}

/** The attributes whose value differs between two states, in the aggregate's own order. */
export function changedAttrs(agg: Aggregate, before: State | null, after: State | null): Attr[] {
  const fields = [...agg.attributes, ...(agg.lifecycle ? [{ name: agg.lifecycle.field } as Attr] : [])];
  return fields.filter((attr) => !sameValue(before?.[attr.name] ?? null, after?.[attr.name] ?? null));
}

/** The command that puts an entry's before-state back: the command it ran, when that was an edit that takes values. */
export function restoreCommand(entry: Entry): { agg: Aggregate; command: Command } | null {
  const agg = aggregateOf(entry.aggregate);
  const command = agg?.commands.find((candidate) => candidate.name === entry.command);
  if (!agg || !command || !entry.before || command.creates || command.destructive || command.attributes.length === 0) return null;
  if (agg.lifecycle?.transitions.some((move) => move.verb === command.name)) return null;
  return { agg, command };
}

/** The arguments of an entry's command that put back what the record held before it. */
export function restoreArguments(entry: Entry, command: Command): State {
  const args: State = {};
  for (const attr of command.attributes) {
    const held = entry.before?.[attr.name];
    if (held !== undefined && held !== null) args[attr.name] = held;
    else if (attr.list) args[attr.name] = [];
  }
  return args;
}

/** Whether a restore would change nothing: the record already holds what the entry's before-state says. */
export function alreadyThat(entry: Entry, command: Command, current: State): boolean {
  return command.attributes.every((attr) => sameValue(entry.before?.[attr.name] ?? (attr.list ? [] : null), current[attr.name] ?? (attr.list ? [] : null)));
}

function line(entry: Entry): string {
  const agg = aggregateOf(entry.aggregate);
  if (!agg) return "";
  const kind = entry.before === null ? "Made" : entry.restores ? `Put back (${entry.label})` : entry.label;
  const changed = changedAttrs(agg, entry.before, entry.after);
  const names = changed.slice(0, 4).map((attr) => labelOf(attr).toLowerCase());
  const what = changed.length === 0 ? "" : `: ${names.join(", ")}${changed.length > 4 ? ` and ${changed.length - 4} more` : ""}`;
  return `${kind}${what}`;
}

function details(entry: Entry): string {
  const agg = aggregateOf(entry.aggregate);
  if (!agg || entry.before === null) return "";
  const rows = changedAttrs(agg, entry.before, entry.after)
    .map((attr) => `<li><span class="font-semibold">${esc(labelOf(attr))}</span>: was ${esc(brief(entry.before?.[attr.name]))}, now ${esc(brief(entry.after?.[attr.name]))}</li>`)
    .join("");
  return rows === "" ? "" : `<details class="basis-full text-sm"><summary class="cursor-pointer text-muted">What changed</summary><ul class="mt-1 list-disc pl-6">${rows}</ul></details>`;
}

function who(entry: Entry): string {
  return entry.by ? esc(entry.by) : `<span class="text-muted">the scheduler</span>`;
}

function item(entry: Entry, agg: Aggregate, id: string, first: boolean): string {
  const found = restoreCommand(entry);
  const own = entry.aggregate === qualified(agg) && entry.id === id;
  const where = own ? "" : ` <span class="text-xs text-muted">(${esc(entry.id)})</span>`;
  const form = found
    ? `<form method="post" action="${esc(href(...at(found.agg), "id", entry.id, "restore"))}"><input type="hidden" name="__entry" value="${esc(entry.n)}"><input type="hidden" name="__back" value="${esc(href(...at(agg), "id", id))}"><button type="submit" class="btn btn-sm">Put it back as it was before</button></form>`
    : "";
  const seconds = Math.floor(Date.parse(entry.at) / 1000);
  return `<li class="flex flex-wrap items-center gap-x-4 gap-y-1 py-3"><span>${momentTime(seconds, "datetime", EDITOR.zone)}</span><span>${who(entry)}</span><span class="font-semibold">${esc(line(entry))}${where}</span>${first && !found ? "" : ""}<span class="ml-auto">${form}</span>${details(entry)}</li>`;
}

/** The History panel of a record, from the entries for it and its companions (newest first). */
export function historyPanel(agg: Aggregate, id: string, entries: Entry[]): string {
  const note = "Changes made through this editor, newest first. A change made another way (another system, a command line) is not listed here.";
  const body =
    entries.length === 0
      ? `<p class="text-muted">No changes through this editor yet. Once this ${esc(agg.name.toLowerCase())} is changed here, who changed it and when will be listed.</p>`
      : `<ul class="divide-y divide-base-300" aria-label="Changes">${entries.slice(0, SHOWN).map((entry, index) => item(entry, agg, id, index === 0)).join("\n")}</ul>${entries.length > SHOWN ? `<p class="mt-2 text-sm text-muted">${entries.length - SHOWN} older ${entries.length - SHOWN === 1 ? "change is" : "changes are"} not shown.</p>` : ""}`;
  return `<section class="border border-base-300 bg-base-100 p-4 sm:p-6" aria-labelledby="history-title">
<h2 id="history-title" class="text-lg">History</h2>
<p class="mb-4 mt-1 max-w-prose text-sm text-muted">${esc(note)}</p>
${body}
</section>`;
}
